package com.fleet.servlet;
import com.fleet.dao.VehicleDAO; import com.fleet.model.Vehicle; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*; import java.util.*;
@WebServlet("/dashboard") public class DashboardServlet extends HttpServlet { protected void doGet(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException { try {req.setAttribute("vehicles",new VehicleDAO().findAll());req.setAttribute("source","MySQL database");} catch(SQLException e){req.setAttribute("vehicles",List.of(new Vehicle("AV-001","ACTIVE",82,"Normal","Sector 62, Noida"),new Vehicle("AV-002","ACTIVE",46,"Normal","Electronic City, Noida"),new Vehicle("AV-003","IDLE",91,"Normal","Fleet Depot"),new Vehicle("AV-004","WARNING",18,"Low battery","Sector 18, Noida"),new Vehicle("AV-005","MAINTENANCE",54,"Sensor issue","Service Centre")));req.setAttribute("source","Sample data — database not connected");} req.getRequestDispatcher("/WEB-INF/views/dashboard.jsp").forward(req,res); } }